<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\Model; use Pterodactyl\Models\Server; use Pterodactyl\Models\Subuser; use Pterodactyl\Models\User; use Illuminate\Database\Eloquent\Builder; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne; class StaffRequest extends Model { public const RESOURCE_NAME = 'staff_request'; public const DIRECTION_OWNER = 'owner_invite'; public const DIRECTION_STAFF = 'staff_request'; public const PENDING = 'pending'; public const CLAIMED = 'claimed'; public const ACTIVE = 'active'; public const DECLINED = 'declined'; public const CANCELLED = 'cancelled'; public const EXPIRED = 'expired'; public const RESOLVED = 'resolved'; public const REVOKED = 'revoked'; public const OPEN_STATUSES = [self::PENDING, self::CLAIMED, self::ACTIVE]; public const CLOSED_STATUSES = [ self::DECLINED, self::CANCELLED, self::EXPIRED, self::RESOLVED, self::REVOKED, ]; protected $table = 'dezerx_staff_requests'; protected $guarded = ['id']; protected $casts = [ 'server_id' => 'int', 'requester_id' => 'int', 'target_staff_id' => 'int', 'staff_id' => 'int', 'permissions' => 'array', 'requires_confirmation' => 'bool', 'duration_minutes' => 'int', 'remaining_minutes' => 'int', 'extension_minutes' => 'int', 'extensions' => 'int', 'handoffs' => 'int', 'claimed_at' => 'datetime', 'approved_at' => 'datetime', 'started_at' => 'datetime', 'expires_at' => 'datetime', 'ended_at' => 'datetime', 'reminded_at' => 'datetime', 'owner_read_at' => 'datetime', 'staff_read_at' => 'datetime', ]; public static array $validationRules = [ 'uuid' => 'required|string|size:36', 'server_id' => 'required|int|exists:servers,id', 'direction' => 'required|string|max:16', 'status' => 'required|string|max:16', 'reason' => 'required|string', 'scope' => 'required|string|max:16', 'permissions' => 'required|array', 'duration_minutes' => 'nullable|int', 'remaining_minutes' => 'nullable|int', 'extension_minutes' => 'nullable|int', ]; public function server(): BelongsTo { return $this->belongsTo(Server::class); } public function requester(): BelongsTo { return $this->belongsTo(User::class, 'requester_id'); } public function target(): BelongsTo { return $this->belongsTo(User::class, 'target_staff_id'); } public function staff(): BelongsTo { return $this->belongsTo(User::class, 'staff_id'); } public function feedback(): HasOne { return $this->hasOne(StaffFeedback::class, 'request_id'); } public function events(): HasMany { return $this->hasMany(StaffRequestEvent::class, 'request_id'); } public function messages(): HasMany { return $this->hasMany(StaffMessage::class, 'request_id'); } public function subuser(): HasOne { return $this->hasOne(Subuser::class, 'dezerx_staff_request_id'); } public function scopeOpen(Builder $builder): Builder { return $builder->whereIn('status', self::OPEN_STATUSES); } public function isPending(): bool { return $this->status === self::PENDING; } public function isClaimed(): bool { return $this->status === self::CLAIMED; } public function isActive(): bool { return $this->status === self::ACTIVE; } public function isOpen(): bool { return in_array($this->status, self::OPEN_STATUSES, true); } public function isOpenEnded(): bool { return $this->duration_minutes === null; } public function hasExpired(): bool { return $this->expires_at !== null && $this->expires_at->isPast(); } public function isUsable(): bool { return $this->isActive() && !$this->hasExpired(); } public function secondsLeft(): ?int { if ($this->expires_at === null) { return null; } return max(0, now()->diffInSeconds($this->expires_at, false)); } public function minutesLeft(): ?int { $seconds = $this->secondsLeft(); return $seconds === null ? null : (int) ceil($seconds / 60); } } 